# Instructions ----
# This file follows the format generated by FIMS:::use_testthat_template().
# Necessary tests include input and output (IO) correctness, edge-case
# handling, and built-in errors and warnings.

test_that("dsem() helper function correctly sets up an AR(1) model", {
  # Description: This is an integration test to verify that the dsem() helper
  # correctly creates and links the DSEMInterface and GMRFDistributionsInterface
  # objects, and that the TMB model produces the correct negative log-likelihood.

  # 1. Setup: Define a simple AR(1) model
  # Model: x_t = rho * x_{t-1} + eps_t, where eps_t ~ N(0, sd^2)
  # We will use 2 time steps, so x = (x1, x2)
  FIMS::initialize_module_objects()

  n_time <- 2
  n_variables <- 1

  # Create a VariableVector for the random effects (x1, x2)
  random_effects <- new(VariableVector)
  random_effects$resize(n_time * n_variables)
  # Set initial values for the random effects vector x
  x_values <- c(0.5, 1.5)
  random_effects$set_values(x_values)
  random_effects$set_estimation_types(rep("random_effects", 2))

  # Define the RAM model
  # Global indices: state 1 is var1@t1, state 2 is var1@t2
  ram <- data.frame(
    type = c(1, 2, 2), # 1=path, 2=variance
    from = c(1, 1, 2),
    to = c(2, 1, 2),
    beta_index = c(1, 2, 3)
  )

  # Define the parameters (rho, sd1, sd2)
  rho <- 0.8
  sd1 <- 1.2 # sd for x1
  sd2 <- 0.5 # sd for innovation of x2
  parameters <- data.frame(
    value = c(rho, sd1, sd2),
    estimation_type = c("fixed_effects", "constant", "constant")
  )

  # 2. IO Correctness: Use the dsem() helper to create the components
  dsem_components <- dsem(
    random_effects = random_effects,
    ram = ram,
    parameters = parameters,
    n_variables = n_variables
  )

  # 3. Run the model and check the NLL
  fims_run <- initialize_fims(components = dsem_components) |>
    fit_fims(optimize = FALSE) # Deterministic run

  # 4. Calculate expected NLL manually
  # Q = (I-Rho)^T * V^-1 * (I-Rho)
  # NLL = 0.5 * (t(x) %*% Q %*% x - log(det(Q)))
  Q <- matrix(0, 2, 2)
  Q[1, 1] <- 1 / (sd1^2) + rho^2 / (sd2^2)
  Q[1, 2] <- -rho / (sd2^2)
  Q[2, 1] <- -rho / (sd2^2)
  Q[2, 2] <- 1 / (sd2^2)
  expected_nll <- 0.5 * (t(x_values) %*% Q %*% x_values - log(det(Q)))

  testthat::expect_equal(fims_run$get_obj(), as.numeric(expected_nll), tolerance = 1e-6)
})